window.DIGEST.following.push(...[{"id": "2112357285775450532", "url": "https://x.com/huang_song_/status/2112357285775450532", "text": "Going back to first principles and building the whole stack in 3D instead of pixels is a bold bet. Congrats to the Viggle team on JST-2. This is the kind of foundational work that moves the field forward.", "name": "Huang Song", "handle": "huang_song_", "avatar": "https://pbs.twimg.com/profile_images/1622938362675068928/dpumO_rh_200x200.jpg", "likes": 10, "rts": 1, "replies": 8, "views": 587, "ts": 1792460197, "media": [], "quote": {"id": "2112202242048528540", "url": "https://x.com/ViggleAI/status/2112202242048528540", "text": "Today we are releasing JST-2, the world's first full-stack physics-native world foundation model.  \n\nMany world models learn in pixel/video space. We went back to first principles and built the entire model stack in 3D.  \n\nGenerate a 3D scene in seconds and expand it in real time. Create characters with motion built in, all through one general architecture.", "name": "ViggleAI", "handle": "ViggleAI", "avatar": "https://pbs.twimg.com/profile_images/2103212981483896832/_Je68a_F_200x200.jpg", "likes": 2141, "rts": 341, "replies": 285, "views": 1412440, "ts": 1792423231, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112198961754746881/vid/avc1/1280x720/aHWyFYw5YBzQqGU9.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112198961754746881/vid/avc1/1920x1080/-hZp9YxkfDfoi5gk.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112198961754746881/img/O1y80k0m3y8uqpNS.jpg", "dur": 105}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 4.59, "thread": [], "tier": "skim"}, {"id": "2112597172156072180", "url": "https://x.com/signulll/status/2112597172156072180", "text": "why do ppl carry around wallets still?\n\ni haven't carried a physical wallet for few years now.\n\nmy pockets just have two things: iphone + airpods.\n\nyou no longer really need anything else to interact with the world.", "name": "signüll", "handle": "signulll", "avatar": "https://pbs.twimg.com/profile_images/1717763325692383232/Jk2PKCx6_200x200.jpg", "likes": 744, "rts": 13, "replies": 714, "views": 175551, "ts": 1792517390, "media": [], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 4.59, "thread": [], "tier": "skim"}, {"id": "2112304427541696637", "url": "https://x.com/danizeres/status/2112304427541696637", "text": "we cooked this episode for y’all\n\nwith our amazing sous chefs @MatthewBerman & @ForwardEditor 🫶🥘", "name": "dani bauer", "handle": "danizeres", "avatar": "https://pbs.twimg.com/profile_images/2000330403731718148/zxD2ZnbH_200x200.jpg", "likes": 23, "rts": 0, "replies": 5, "views": 2270, "ts": 1792447594, "media": [], "quote": {"id": "2112242739198959913", "url": "https://x.com/OpenAIDevs/status/2112242739198959913", "text": "Here’s what we’re cooking with Codex:\n\nhttps://x.com/i/broadcasts/1RKZzBELBbXKB", "name": "OpenAI Developers", "handle": "OpenAIDevs", "avatar": "https://pbs.twimg.com/profile_images/2022002720971096064/l3Kyt4qt_200x200.jpg", "likes": 1409, "rts": 77, "replies": 305, "views": 1705249, "ts": 1792432887, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 4.58, "thread": [], "tier": "skim"}, {"id": "2112210819366945222", "url": "https://x.com/AntLingAGI/status/2112210819366945222", "text": "Audio for meetings, interviews & voice-driven services.\n\nMing-3.0-audio-flash summarizes long recordings, answers spoken questions, understands music & ambient sound, and generates tool requests for apps to execute.\n\nMing-3.0-audio-flash offers a more efficient deployment option.", "name": "Ant Ling", "handle": "AntLingAGI", "avatar": "https://pbs.twimg.com/profile_images/1911666162137477120/EbzxHHzp_200x200.jpg", "likes": 39, "rts": 1, "replies": 1, "views": 2557, "ts": 1792425276, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112205138073165824/vid/avc1/1280x720/nu1yI0ZgmYCvCaLf.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112205138073165824/vid/avc1/1920x1080/kGDDyky9jSISvL9R.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112205138073165824/img/A0Uv1WVrvjIFOG_c.jpg", "dur": 226}], "quote": null, "reply_to": "2112210816149897641", "cat": "AI Tools & Agents", "score": 4.57, "thread": [{"id": "2112210811997540475", "url": "https://x.com/AntLingAGI/status/2112210811997540475", "text": "Today, we're open-sourcing 5 Ming-3.0 models across 3 speech families.\n\n- Ming-3.0-tts: 0.5B voice design & paralinguistic cues; Tiny 7.9B A1.3B long-form speech.\n- Ming-3.0-audio: Flash 126B A6.5B understanding & tools; Tiny 9.3B A2.7B efficient dialogue.\n- Ming-3.0-asr: Tiny 8.6B A2B dialects & context.", "name": "Ant Ling", "handle": "AntLingAGI", "avatar": "https://pbs.twimg.com/profile_images/1911666162137477120/EbzxHHzp_200x200.jpg", "likes": 946, "rts": 130, "replies": 77, "views": 612492, "ts": 1792425275, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVAOsJDboAAKJaP.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVAULxqasAAhy5u.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVAUM-9asAAcHia.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVAUOaQbIAANuKN.jpg?name=orig"}], "quote": null, "reply_to": null}, {"id": "2112210816149897641", "url": "https://x.com/AntLingAGI/status/2112210816149897641", "text": "TTS for stories, narration & voice assistants.\n\nDesign voices in text. Direct emotion, pace & emphasis. Add laughter or sighs. 7 languages.\n- #1 open-weight model in AA Controlled Voice (1069 Elo).\n- #3 on Provider Voice (1188 Elo)\n- Ties #1 among all models on Pronunciation Robustness (93.2%).", "name": "Ant Ling", "handle": "AntLingAGI", "avatar": "https://pbs.twimg.com/profile_images/1911666162137477120/EbzxHHzp_200x200.jpg", "likes": 52, "rts": 1, "replies": 4, "views": 4376, "ts": 1792425276, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112204995089326080/vid/avc1/1280x720/KzMVe4xY3JZks9xs.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112204995089326080/vid/avc1/1920x1080/ztrcf4ZHoa3zxRNo.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112204995089326080/img/emlfiMNeqGwbaM09.jpg", "dur": 252}], "quote": null, "reply_to": "2112210811997540475"}], "tier": "skim"}, {"id": "2112474512323219780", "url": "https://x.com/ControlAI/status/2112474512323219780", "text": "NEW: Lord Wallace of Saltaire has backed our campaign for binding regulation on the most powerful AI systems!\n\nHe joins 180+ UK parliamentarians, the largest such coalition anywhere in the world, who recognize the risk of human extinction posed by superintelligent AI.", "name": "ControlAI", "handle": "ControlAI", "avatar": "https://pbs.twimg.com/profile_images/1905309869776699392/tpKv9Ny4_200x200.jpg", "likes": 10, "rts": 2, "replies": 1, "views": 592, "ts": 1792488146, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVEEX9aWEAAecmL.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "Research & Safety", "score": 4.56, "thread": [], "tier": "skim"}, {"id": "2112248089495167296", "url": "https://x.com/nollahealth/status/2112248089495167296", "text": "Nolla Health has submitted comments to the FDA on its proposed approach to evaluating Generative AI-Enabled Medical Devices.\n\nWe applaud the FDA for inviting this conversation and look forward to working with the agency as increasingly capable AI systems take on defined roles in healthcare. Building that future requires rigorous evidence, clear accountability, and a commitment to protecting patients.\n\nOur experience in Utah informs these comments.\n\nIn the attached video, the State of Utah’s team explains what gave them confidence in Nolla’s approach: a carefully bounded starting point, evaluation before deployment, and a workflow that considers where AI can help and when a patient needs a clinician. We’re grateful to Utah for championing technological progress with patient safety at the center, while seeking to earn and protect public trust.\n\nOur comments encourage an approach grounded in clinical evidence, appropriate oversight, and clear accountability, with practical pathways for safely evaluating and improving AI systems. We also support early coordination between state and federal efforts so lessons from state-supervised pilots can inform FDA’s review.\n\nFrom Utah to the national conversation, our goal is the same: help more patients benefit from AI safely and effectively, and earn their trust as we move forward.\n\nWe expect our full comments to be available on http://Regulations.gov soon, following agency review.", "name": "Nolla Health", "handle": "nollahealth", "avatar": "https://pbs.twimg.com/profile_images/1943384766192959488/G_kdCDAr_200x200.png", "likes": 28, "rts": 2, "replies": 2, "views": 2954, "ts": 1792434162, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112246296358916096/vid/avc1/1280x720/ijVS0Nv9T3tuZLx8.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112246296358916096/vid/avc1/1920x1080/Y2yUYTSazy9pH2Li.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112246296358916096/img/ZIesyT1NycwwoYou.jpg", "dur": 119}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 4.56, "thread": [], "tier": "skim"}, {"id": "2112563128487514512", "url": "https://x.com/GradiumAI/status/2112563128487514512", "text": "A new frontier for on-device speech.\n\nWe're open-sourcing Phonon, a suite of TTS models under 50m parameters, setting a new standard for naturalness and accuracy across languages, with the broadest inference support to date.\n\nPhonon-31m is available under Apache 2.0.\n\nhttps://gradium.ai/phonon🧵", "name": "Gradium", "handle": "GradiumAI", "avatar": "https://pbs.twimg.com/profile_images/2085285740032745472/0_Hbd7an_200x200.png", "likes": 1410, "rts": 213, "replies": 119, "views": 189182, "ts": 1792509274, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112562730771054594/vid/avc1/1280x720/oZwtZ8OWhERvzCza.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112562730771054594/vid/avc1/1920x1080/Nn4dJJERlVpw_pKT.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112562730771054594/img/mQzM0zRPbfBd8e2M.jpg", "dur": 48}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 4.56, "thread": [], "tier": "skim"}, {"id": "2112206606255436050", "url": "https://x.com/dcmotz/status/2112206606255436050", "text": "been having fun making quick webgl sketches and toys with Gemini 4 Argon. I screencapped them and it edited together this reel. then I described the soundtrack I wanted and it procedurally composed it in raw C++ math... just to flex on me I think", "name": "Dan Motzenbecker", "handle": "dcmotz", "avatar": "https://pbs.twimg.com/profile_images/851864981821833216/AjUNIfhK_200x200.jpg", "likes": 28, "rts": 3, "replies": 3, "views": 5767, "ts": 1792424272, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112205072536944640/vid/avc1/540x540/ZuGaOupvz44mNTYn.mp4?tag=14", "hd": "https://video.twimg.com/amplify_video/2112205072536944640/vid/avc1/720x720/EpC6RwAlydoskhLv.mp4?tag=14", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112205072536944640/img/JHMIExX03BjRwIAA.jpg", "dur": 20}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 4.55, "thread": [], "tier": "skim"}, {"id": "2112292242438361499", "url": "https://x.com/AniC_dev/status/2112292242438361499", "text": "parallel design & UX hillclimbing with agents and cloud desktops\n\nthat's one of the best emerging usecases of https://boat.dev \n\nit's what I've been using to improve our dashboard, landing page and do the cool launch videos", "name": "Anicet", "handle": "AniC_dev", "avatar": "https://pbs.twimg.com/profile_images/1968045619248877568/XrGi-opy_200x200.jpg", "likes": 24, "rts": 2, "replies": 1, "views": 2407, "ts": 1792444689, "media": [], "quote": {"id": "2112290271211962556", "url": "https://x.com/milindlabs/status/2112290271211962556", "text": "this is how you should be stress testing your product before a launch\n\nyou spin up multiple bots with their own unique personalities on @mausbot_ \n\ngive them their own @boatdotdev computers \n\nthen let them loose on your product, all at once, each attacking it from a different angle\n\nand you watch every one of them on a live canvas\n\nfind what breaks before your customers do", "name": "Milind S", "handle": "milindlabs", "avatar": "https://pbs.twimg.com/profile_images/2041000459142627328/BPq9HFJ-_200x200.jpg", "likes": 88, "rts": 8, "replies": 4, "views": 7256, "ts": 1792444219, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112287533166104576/vid/avc1/1072x720/BosnUCjOk0dcy9oa.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112287533166104576/vid/avc1/3220x2160/nB9Y1Mgyk_bT83K5.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112287533166104576/img/DBDFNbveDO9Xu9j5.jpg", "dur": 88}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 4.55, "thread": [], "tier": "skim"}, {"id": "2112219429803036905", "url": "https://x.com/j3nnings/status/2112219429803036905", "text": "It's TikTok for code review 🤯\n\nEvery PR gets a short video of an AI agent actually using your app.\n\nSwipe through, spot the bug, merge.\n\n...and it's free to try.", "name": "Ian Jennings", "handle": "j3nnings", "avatar": "https://pbs.twimg.com/profile_images/1283158928721883142/0Yg9wGgr_200x200.jpg", "likes": 40, "rts": 0, "replies": 0, "views": 96639, "ts": 1792427329, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HMBN_eNWUAA_qKh.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 4.54, "thread": [], "tier": "skim"}, {"id": "2112220243930354049", "url": "https://x.com/ecomchasedimond/status/2112220243930354049", "text": "Every group chat has a trip that’s been “happening soon” for three years.\n\n@wabi is an AI assistant you use together to find dates, build the itinerary, and book flights.\n\nAs the unofficial travel agent, I’d love to see that trip finally make it out of the group chat.", "name": "Chase Dimond | Email Marketing Nerd 📧", "handle": "ecomchasedimond", "avatar": "https://pbs.twimg.com/profile_images/1669746653522264064/7BkzAuBa_200x200.jpg", "likes": 21, "rts": 6, "replies": 0, "views": 4595, "ts": 1792427523, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVAdCgdbgAAfz7z.jpg?name=orig"}], "quote": {"id": "2112212804979880239", "url": "https://x.com/ekuyda/status/2112212804979880239", "text": "Wabi 2.0 is live!\n\npersonal agents are one person, one chat. but the parts of life that matter run on more than one person\n\nWabi is an agent you use together. you talk to it, it does stuff, builds the apps you need, and anyone can join the thread - your partner, your best friend, the preschool moms groupchat\n\nschool changes pickup time → Wabi updates the family calendar, everyone sees it.\na show you’d both love → Wabi finds a night that works, gets the tickets.\nthe trip everyone keeps talking about → Wabi picks the dates, builds the itinerary, books it\n\ngo start a thread with your people 👇", "name": "Eugenia Kuyda", "handle": "ekuyda", "avatar": "https://pbs.twimg.com/profile_images/2105081341352263680/H9RzWr7T_200x200.jpg", "likes": 1673, "rts": 218, "replies": 353, "views": 1848743, "ts": 1792425750, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112212457234284544/vid/avc1/1280x720/HW0ErfX-0u7kWbHU.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112212457234284544/vid/avc1/3840x2160/4gITKDb_F7iviaVH.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112212457234284544/img/Wzg-bjHfnRT2-0FG.jpg", "dur": 75}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 4.53, "thread": [], "tier": "skim"}, {"id": "2112272044524216788", "url": "https://x.com/mercor/status/2112272044524216788", "text": "Last week, Mercor Research economist @aden_barton  joined @MTSlive to discuss our latest study comparing frontier AI models with licensed accountants on real-world accounting tasks.\n\n18 months ago, the best models performed below the average accountant. Today, models are faster and more accurate than every accountant in our study.\n\nAden discussed what this progress means for the accounting profession, and why performing well on individual tasks is different from doing an entire job.\n\nWatch the full conversation. https://www.youtube.com/watch?v=9JcfR1Lbx4c", "name": "Mercor", "handle": "mercor", "avatar": "https://pbs.twimg.com/profile_images/2051774732341854208/DR6w6FDH_200x200.jpg", "likes": 24, "rts": 1, "replies": 3, "views": 9479, "ts": 1792439874, "media": [], "quote": null, "reply_to": null, "cat": "Research & Safety", "score": 4.53, "thread": [], "tier": "skim"}, {"id": "2112598493672181921", "url": "https://x.com/dasha_shunina/status/2112598493672181921", "text": "AI agents are writing more code than ever.\n\nBut who's actually going to control the future of software development? 👀\n\nNext week, we're bringing @cline  × @OpenRouter together to talk open vs. closed AI, model choice, and developer freedom.\n\nBring your questions. \n\nhttps://luma.com/dtzhn1ux", "name": "Dasha", "handle": "dasha_shunina", "avatar": "https://pbs.twimg.com/profile_images/1996367316494553088/mOGjb4RE_200x200.jpg", "likes": 6, "rts": 1, "replies": 1, "views": 346, "ts": 1792517705, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 4.53, "thread": [], "tier": "skim"}, {"id": "2112411837237231768", "url": "https://x.com/WeMakeDevs/status/2112411837237231768", "text": "Mergetober is a chance to contribute to open source, build useful integrations, and get your PRs merged into projects that developers use 🚀\n\nWork on integrations for @cognee_, get your contributions reviewed, and you could be one of 20 randomly selected contributors to win $100 for a merged PR.\n\nFind an issue and start contributing.\n\nRegister here: https://www.wemakedevs.org/hackathons/mergetober", "name": "WeMakeDevs", "handle": "WeMakeDevs", "avatar": "https://pbs.twimg.com/profile_images/2084632260423077888/wo9kVyJ5_200x200.jpg", "likes": 12, "rts": 2, "replies": 1, "views": 1504, "ts": 1792473203, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVDLPMyawAAqNf1.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 4.52, "thread": [], "tier": "skim"}, {"id": "2112621635450950116", "url": "https://x.com/steipete/status/2112621635450950116", "text": "@torchandzen Yeah but the first with a governance model I trust.", "name": "Peter Steinberger 🦞", "handle": "steipete", "avatar": "https://pbs.twimg.com/profile_images/1131851609774985216/OcsssQ9J_200x200.png", "likes": 5, "rts": 1, "replies": 1, "views": 862, "ts": 1792523223, "media": [], "quote": null, "reply_to": "2112621164938002558", "cat": "AI Models & Labs", "score": 4.52, "thread": [{"id": "2112621164938002558", "url": "https://x.com/torchandzen/status/2112621164938002558", "text": "isn't that the third rust typescript compiler in a month or something?", "name": "Theodore Keloglou", "handle": "torchandzen", "avatar": "https://pbs.twimg.com/profile_images/1914888352861450240/t1XjuX7B_200x200.jpg", "likes": 2, "rts": 0, "replies": 1, "views": 669, "ts": 1792523110, "media": [], "quote": {"id": "2112571535731106013", "url": "https://x.com/steipete/status/2112571535731106013", "text": "Moved to tsrs over the weekend. Drop-in replacement. Around 5x faster for OC.\n\nKind of amazing that it took Microsoft a team and two years to rewrite the TS compiler in go, and now you can just let an agent rip and get sth significantly better within weeks.", "name": "Peter Steinberger 🦞", "handle": "steipete", "avatar": "https://pbs.twimg.com/profile_images/1131851609774985216/OcsssQ9J_200x200.png", "likes": 2114, "rts": 60, "replies": 104, "views": 158634, "ts": 1792511278, "media": [], "quote": null, "reply_to": null}, "reply_to": null}], "tier": "skim"}, {"id": "2112211093041143985", "url": "https://x.com/ai_for_success/status/2112211093041143985", "text": "We always talks about which AI model is the smartest, but when you build agents, the real bottleneck is often getting clean data from the web.\n\nI've seen how blocked pages, JavaScript rendering, and changing website layouts can get in the way of what an agent is trying to do.\n\nThat's the problem Context[.] dev is working to solve, giving agents a simpler way to access web data.\n\nA smarter model is great, but better data might make a much bigger difference than the next model upgrade.", "name": "AshutoshShrivastava", "handle": "ai_for_success", "avatar": "https://pbs.twimg.com/profile_images/1687401026805256192/uQ1o2wVQ_200x200.jpg", "likes": 25, "rts": 1, "replies": 5, "views": 2874, "ts": 1792425342, "media": [], "quote": {"id": "2112208794847699032", "url": "https://x.com/mynameisyahia/status/2112208794847699032", "text": "We raised $9M to give your agents the internet.\n\nLed by @generalcatalyst, with @orangecollectv and Robinhood Ventures.\n\nSearch, scrape, crawl, monitor with one API trusted by 800+ customers.\n\nWe’re making it ridiculously easy to build with web data.", "name": "Yahia Bakour", "handle": "mynameisyahia", "avatar": "https://pbs.twimg.com/profile_images/1880738459876311040/ML-dZoFx_200x200.jpg", "likes": 1380, "rts": 102, "replies": 471, "views": 282225, "ts": 1792424794, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112205600771952640/vid/avc1/1280x720/Ytj3YlePWPDBb0ZT.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112205600771952640/vid/avc1/1920x1080/U8vjeTcYKtkmN_8J.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112205600771952640/img/sS6sSwGBAJZ27zTO.jpg", "dur": 45}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 4.51, "thread": [], "tier": "skim"}, {"id": "2112224258273243315", "url": "https://x.com/FishAudio/status/2112224258273243315", "text": "Spooky voices from Fish Audio, now on @livekit 🎃 Try them out and build something creepy this Halloween 👻", "name": "Fish Audio", "handle": "FishAudio", "avatar": "https://pbs.twimg.com/profile_images/2081294228852989952/IIWh4zkw_200x200.jpg", "likes": 26, "rts": 1, "replies": 4, "views": 3280, "ts": 1792428481, "media": [], "quote": {"id": "2112219529312981468", "url": "https://x.com/livekit/status/2112219529312981468", "text": "Meet SpookyKit, five haunted voices for your voice agent 🎃\n\nVoices from LiveKit coworkers (guess who?), via @FishAudio as a custom voice:\n🕯️ the hollow whisperer (v_rcMdmMksGhqr)\n📞 the grave caller (v_ou7cbav4LMuq)\n🌊 the thing below (v_U9DZ7HDMqqtM)\n\nVoices summoned from the shadows by our spooky friends at @GradiumAI 🧡\n💀 the bone barker (hwchrc8s07s20000)\n📻 the dead air host (hwchrc8s07s00000)\n\npaste a voice ID into LiveKit Inference or Agent Builder and go give someone a fright 👻\n\nTry them now >\nhttp://cloud.livekit.io", "name": "LiveKit", "handle": "livekit", "avatar": "https://pbs.twimg.com/profile_images/1791157444829380609/M6p5M6-A_200x200.png", "likes": 49, "rts": 4, "replies": 6, "views": 7262, "ts": 1792427353, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112219501215264768/vid/avc1/720x720/S843q14l5hUk_Ymh.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112219501215264768/vid/avc1/1080x1080/FfMY1T8IxdtD6aQW.mp4?tag=16", "thumb": "https://pbs.twimg.com/media/HVAcd8bW0AAE_qw.jpg", "dur": 42}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 4.51, "thread": [], "tier": "skim"}, {"id": "2112585847556149542", "url": "https://x.com/MTSlive/status/2112585847556149542", "text": "SITUATION UPDATE: Trump Accounts may be expanded to anyone under 40 years old, making 100 million more people eligible for the SpaceX shares Elon Musk is scheduled to donate in 2027, per New York Post.", "name": "MTS", "handle": "MTSlive", "avatar": "https://pbs.twimg.com/profile_images/2057947669281263616/aovpVL4b_200x200.jpg", "likes": 1645, "rts": 50, "replies": 40, "views": 95423, "ts": 1792514690, "media": [], "quote": null, "reply_to": null, "cat": "Politics & World", "score": 4.51, "thread": [], "tier": "skim"}, {"id": "2112198926161883515", "url": "https://x.com/ardabrowski/status/2112198926161883515", "text": "I've been building ecommerce agents for a while and tried many AI frameworks along the way. I must say:\n\n@eve is the first one that really clicked.\n\nI told @shardara this recently and he asked me why, so I thought it was worth sharing publicly.\n\nIn my first AI consulting gigs (mostly custom shopping assistants) I was stunned by how much infra work it takes to ship an agent. I'd say 60–70% of my time went into infra, and only the rest into the actual AI work: context engineering, data, evals. That was insane tbh, because none of that infra felt custom to me. Most frameworks either didn’t help much with infra, or if they did, they forced clunky abstractions on the AI side, and I kept fighting the framework instead of doing my work.   \n\nThat's probably why so many folks say \"don't use a framework, just build from scratch.\" I felt that too (we all have our Claudes and Codexes, right?), but going framework-less never felt right either. There’s so much repeatable stuff, and way too many footguns, to rebuild it every time.\n\nSo for a long time I was looking for something very simple:\n1. Pls pls handle infra for me. Durable execution, sandboxes, streaming, reconnects, subagents, file uploads that land in the sandbox, auth, web search, easy deployment.\n2. LEAVE ME FREEDOM on the AI part. I want to own the harness, not have the framework own it for me.\n\n@eve  is just the first one that ticks all these boxes. \n\nBonus: every production agent quickly needs a UI and often a custom API. A playground, a context view, a domain-specific data viewer (inspired by @HamelHusain, highly recommend). With Eve + Next.js it’s all in a single repo (not even a monorepo!), deployed with one click. Framework-defined Infrastructure at its finest, it really feels good.\n\nbtw, I come from front-end world and I remember exactly how the world looked before and after nextjs. Now it feels like this again, just with AI.\n\nEverything we do at the eCommerce AI Lab at @commerce_ui now runs on Eve: shopping assistants and analytics agents for our clients, plus our own company agent that lives in Slack. It all just works, and a huge amount of custom code just evaporated.\n\nHighly recommend", "name": "Andrzej Dąbrowski", "handle": "ardabrowski", "avatar": "https://pbs.twimg.com/profile_images/1646136679407779842/2UphpuW6_200x200.jpg", "likes": 20, "rts": 4, "replies": 4, "views": 2695, "ts": 1792422441, "media": [], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 4.51, "thread": [], "tier": "skim"}, {"id": "2100235676692398462", "url": "https://x.com/AIatAMD/status/2100235676692398462", "text": "What if your next AI breakthrough started at your desk?\n\nAMD Ryzen AI Halo is designed to help shorten the distance between an idea and a working model by bringing AI development closer to where work happens. Hear more from Jack Huynh at Advancing AI.", "name": "AI at AMD", "handle": "AIatAMD", "avatar": "https://pbs.twimg.com/profile_images/1910711325321240579/Mzhoz-iM_200x200.jpg", "likes": 153, "rts": 7, "replies": 12, "views": 837179, "ts": 1789570180, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2100235570114879488/vid/avc1/480x852/dhV1ZWmG-UXtQxQd.mp4?tag=14", "hd": "https://video.twimg.com/amplify_video/2100235570114879488/vid/avc1/720x1280/sZtoUkKuNRJiu6PW.mp4?tag=14", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2100235570114879488/img/CgLRxHdD29vPO-1F.jpg", "dur": 21}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 4.5, "thread": [], "tier": "skim"}, {"id": "2112603027769352687", "url": "https://x.com/Pushkarm029/status/2112603027769352687", "text": "Stop burning thousands of dollars on AI credits.\n\nNot every task needs Opus 5.5 or Astra. And not every company needs to be locked into proprietary AI systems.\n\nYou can run Qwen, DeepSeek, or GLM locally.\n\nInstead of GrokBot, try OpenBot.\n\nThere are already powerful open-source alternatives for almost everything. You can own your AI stack, keep your data private, and stop depending on a single provider.\n\nWe’re entering the age of AI abundance. Start taking advantage of it.\n\nThe biggest challenge? Setup and maintenance.\n\nYou can use Opus to help set it up yourself. Or just DM me.\n\nI’m already working with a few large companies in Eastern Europe to build self-hosted AI infrastructure, reduce vendor dependency, and future-proof their systems.\n\nIf your company is spending thousands on AI every month, let’s see how much of that you can replace with open source.\n\nMy DMs are open.", "name": "pushkar", "handle": "Pushkarm029", "avatar": "https://pbs.twimg.com/profile_images/2087914210118500352/DrJI-C40_200x200.jpg", "likes": 5, "rts": 1, "replies": 1, "views": 168, "ts": 1792518786, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 4.5, "thread": [], "tier": "skim"}, {"id": "2112745495026438225", "url": "https://x.com/shaunmmaguire/status/2112745495026438225", "text": "Spam calls should be illegal\n\nAnd there should be enforcement of this", "name": "Shaun Maguire", "handle": "shaunmmaguire", "avatar": "https://pbs.twimg.com/profile_images/1942940317784719360/47aIqszK_200x200.jpg", "likes": 853, "rts": 39, "replies": 68, "views": 32154, "ts": 1792552753, "media": [], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 4.5, "thread": [], "tier": "skim"}, {"id": "2112577878680576246", "url": "https://x.com/KobeissiLetter/status/2112577878680576246", "text": "Day 2 of the \"Black Monday\" crash:\n\nThe Dow is now up +500 points today and the S&P 500 is 1.5% away from a new record high.\n\nFor the 10th+ time since 2025, \"Black Monday\" calls failed to materialize.\n\nWe maintain our outlook as outlined below.", "name": "The Kobeissi Letter", "handle": "KobeissiLetter", "avatar": "https://pbs.twimg.com/profile_images/1975243710846640128/fwYCe67Y_200x200.jpg", "likes": 1320, "rts": 98, "replies": 124, "views": 184817, "ts": 1792512790, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112577753224478720/vid/avc1/1280x720/w1-EFwBKmjRTq30v.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112577753224478720/vid/avc1/1920x1080/F1slcL4lvTxeJNH7.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112577753224478720/img/QGtaQZJUUADEgvRX.jpg", "dur": 18}], "quote": {"id": "2111679803560796451", "url": "https://x.com/KobeissiLetter/status/2111679803560796451", "text": "Calls for a \"Black Monday\" are spreading rapidly across social media right now.\n\nIf history is any guide, this means the S&P 500 should hit 8,000 soon.\n\nIgnore the noise. Read our analysis below.", "name": "The Kobeissi Letter", "handle": "KobeissiLetter", "avatar": "https://pbs.twimg.com/profile_images/1975243710846640128/fwYCe67Y_200x200.jpg", "likes": 9403, "rts": 774, "replies": 448, "views": 2216392, "ts": 1792298672, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "Everything Else", "score": 4.49, "thread": [], "tier": "skim"}, {"id": "2112591612820037855", "url": "https://x.com/dhaiwat/status/2112591612820037855", "text": "so this is how you unite this country", "name": "Dhaiwat", "handle": "dhaiwat", "avatar": "https://pbs.twimg.com/profile_images/2110578752581419008/Si76IqY8_200x200.jpg", "likes": 1535, "rts": 57, "replies": 39, "views": 58248, "ts": 1792516065, "media": [], "quote": {"id": "2112483997762863187", "url": "https://x.com/dhaiwat/status/2112483997762863187", "text": "cricket 07 with an online multiplayer mode. play with your friends\n\nall you need is a web browser\n\nlink: https://cricket07.dhaiwat.com", "name": "Dhaiwat", "handle": "dhaiwat", "avatar": "https://pbs.twimg.com/profile_images/2110578752581419008/Si76IqY8_200x200.jpg", "likes": 9345, "rts": 912, "replies": 405, "views": 638306, "ts": 1792490407, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVEL_UxakAANyEt.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVEMQoIawAAjm1_.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVEMsEPboAA9lbe.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "Sports", "score": 4.49, "thread": [], "tier": "skim"}, {"id": "2112245968750145561", "url": "https://x.com/AIatMeta/status/2112245968750145561", "text": "We trained our Muse foundational models, including Muse Wonder, at Prometheus, our gigawatt-scale supercluster in New Albany, Ohio.\n\nAcross a supercluster with hundreds of thousands of GPUs, even one underperforming host can slow an entire training run. We engineered Prometheus for resilience at scale, achieving 85%+ goodput on pretraining, 90%+ on reinforcement learning and ~47K GPU hours mean time between interruptions during Muse Wonder training.\n\nTake a look at the tech powering Prometheus: https://go.meta.me/4yXXApZ", "name": "AI at Meta", "handle": "AIatMeta", "avatar": "https://pbs.twimg.com/profile_images/2102933421458665472/o_KTIjw3_200x200.png", "likes": 3961, "rts": 318, "replies": 169, "views": 389301, "ts": 1792433657, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112245058472906752/vid/avc1/1280x720/Po6sJW0llIrgOpor.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112245058472906752/vid/avc1/1920x1080/A15F6uYoUrUyPB9v.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112245058472906752/img/Ql2HvTqHqzURK5DP.jpg", "dur": 24}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 4.48, "thread": [], "tier": "skim"}, {"id": "2112651687278350662", "url": "https://x.com/JaapVergote/status/2112651687278350662", "text": "For all the @ShopifyDevs: security is now non-negotiable. A year ago it might have been an afterthought, but access to Shopify's API's comes with a  duty to secure your software.\n\nHighly recommend @AikidoSecurity It's free, fast and built for devs", "name": "Jaap Vergote", "handle": "JaapVergote", "avatar": "https://pbs.twimg.com/profile_images/1876323097009172480/L9ugwBMu_200x200.jpg", "likes": 6, "rts": 0, "replies": 1, "views": 98, "ts": 1792530388, "media": [], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 4.48, "thread": [], "tier": "skim"}, {"id": "2112199484679532717", "url": "https://x.com/robot_xyz_rpy/status/2112199484679532717", "text": "NVIDIA's new Robota-Embed paper reports robot success rising from 24% to 68% on 5 selected simulation tasks, without retraining the AI models.\n\nThe change was a memory of past attempts and better rules for choosing useful examples.\n\nMy take: robotics needs better ways to reuse experience, alongside better models. That could give teams another way to improve robots after deployment.\n\nWith MIT, UC Berkeley, Oxford and CMU.\nBy @YunzeLiu_ai @NickySGJingWang @WushrLance @HeWenkun1228 and 15 coauthors.\n\n1/8", "name": "Ali", "handle": "robot_xyz_rpy", "avatar": "https://pbs.twimg.com/profile_images/2097748475827859456/E5-roc3G_200x200.jpg", "likes": 23, "rts": 3, "replies": 2, "views": 1005, "ts": 1792422574, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112199448910524418/vid/avc1/1280x720/hJcFFaCjSRrAiKQ3.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112199448910524418/vid/avc1/1920x1080/vtX7ZpLp7Aeibe7X.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112199448910524418/img/VLoovO_go2q8zx41.jpg", "dur": 30}], "quote": null, "reply_to": null, "cat": "Research & Safety", "score": 4.47, "thread": [], "tier": "skim"}, {"id": "2112723244390187048", "url": "https://x.com/20060702zyl/status/2112723244390187048", "text": "将你的codex和Claude code 变成grok bot", "name": "克劳德（浇朋友版）", "handle": "20060702zyl", "avatar": "https://pbs.twimg.com/profile_images/2099367565831344128/I0yuj2PV_200x200.jpg", "likes": 1, "rts": 1, "replies": 1, "views": 349, "ts": 1792547448, "media": [], "quote": {"id": "2112228154651881479", "url": "https://x.com/trycua/status/2112228154651881479", "text": "1/ Introducing the Cua Spaces SDK.\n\nEvery big lab now ships a bot with its own computer: Grok Bot, Muse, dots. None let you bring your own. With Cua Spaces, now you can. \n\nPut Claude Code, Codex or any agent on compute you choose, and run jobs across all your computers at once.", "name": "Cua", "handle": "trycua", "avatar": "https://pbs.twimg.com/profile_images/2106056584929361920/XJWz9bZS_200x200.jpg", "likes": 3237, "rts": 222, "replies": 158, "views": 410187, "ts": 1792429410, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112223219252088832/vid/avc1/1280x720/I6_NaL1Cg-XWB-iq.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112223219252088832/vid/avc1/1920x1080/AHMslWsH_vMoQKku.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112223219252088832/img/EHvyGokJ8bsir4qa.jpg", "dur": 12}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 4.47, "thread": [], "tier": "skim"}, {"id": "2112455717299048869", "url": "https://x.com/TimJayas/status/2112455717299048869", "text": "i wasn't expecting gpt-6.5 to drop by the end of 28 day challenge, this alone gives me hope that openai can make a bigger comeback than everyone expected\n\neveryone who said they wouldn't switch back to codex is going to have a hard time resisting next month", "name": "Tim Jayas", "handle": "TimJayas", "avatar": "https://pbs.twimg.com/profile_images/2016190209768226821/MW5mAfL-_200x200.jpg", "likes": 11, "rts": 0, "replies": 2, "views": 833, "ts": 1792483665, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 4.46, "thread": [], "tier": "skim"}, {"id": "2112559236379009210", "url": "https://x.com/blakeurmos/status/2112559236379009210", "text": "I see people asking questions about “using claude and codex subscriptions with this”\n\njust use claude opus 5.5 to build your own agent workspace and you can use any harness and model you want\n\nand you don’t have to battle the opinions of others.", "name": "Blake Urmos", "handle": "blakeurmos", "avatar": "https://pbs.twimg.com/profile_images/1982117584699867136/nasIzGeC_200x200.jpg", "likes": 7, "rts": 1, "replies": 0, "views": 1441, "ts": 1792508346, "media": [], "quote": {"id": "2112228154651881479", "url": "https://x.com/trycua/status/2112228154651881479", "text": "1/ Introducing the Cua Spaces SDK.\n\nEvery big lab now ships a bot with its own computer: Grok Bot, Muse, dots. None let you bring your own. With Cua Spaces, now you can. \n\nPut Claude Code, Codex or any agent on compute you choose, and run jobs across all your computers at once.", "name": "Cua", "handle": "trycua", "avatar": "https://pbs.twimg.com/profile_images/2106056584929361920/XJWz9bZS_200x200.jpg", "likes": 3237, "rts": 222, "replies": 158, "views": 410187, "ts": 1792429410, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112223219252088832/vid/avc1/1280x720/I6_NaL1Cg-XWB-iq.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112223219252088832/vid/avc1/1920x1080/AHMslWsH_vMoQKku.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112223219252088832/img/EHvyGokJ8bsir4qa.jpg", "dur": 12}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 4.44, "thread": [], "tier": "skim"}, {"id": "2112588931342471315", "url": "https://x.com/onkeiki/status/2112588931342471315", "text": "Resend Forward is live from SF tomorrow, so we made it an agent.\n\nAsk who’s on the main stage, what’s next, or where to catch the stream: +1 (415) 718-8445", "name": "Keiki", "handle": "onkeiki", "avatar": "https://pbs.twimg.com/profile_images/2092638981854834688/aVQTfa03_200x200.jpg", "likes": 3, "rts": 2, "replies": 0, "views": 348, "ts": 1792515425, "media": [], "quote": {"id": "2112588344689389755", "url": "https://x.com/orchid_hq/status/2112588344689389755", "text": "Going to Resend Forward? We built an agent for it.\n\nText it anything: the agenda, the speakers, where to go next.\n\n+1 (415) 718-8445\n\nBuilt on @onkeiki.", "name": "Orchid", "handle": "orchid_hq", "avatar": "https://pbs.twimg.com/profile_images/2057121416021938176/zja3VcCi_200x200.jpg", "likes": 32, "rts": 7, "replies": 2, "views": 4245, "ts": 1792515286, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFegcAWAAAXVMy.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 4.44, "thread": [], "tier": "skim"}, {"id": "2112216643422085406", "url": "https://x.com/MaxHirsch13/status/2112216643422085406", "text": "Wow this is incredibly useful \n\nAnyone who has done marketing knows it can be PAINFUL on LinkedIn. \n\nSuper excited to try this one out", "name": "max", "handle": "MaxHirsch13", "avatar": "https://pbs.twimg.com/profile_images/2086274175333732352/Hf8XV0Td_200x200.jpg", "likes": 26, "rts": 0, "replies": 3, "views": 1767, "ts": 1792426665, "media": [], "quote": {"id": "2112214318611837243", "url": "https://x.com/polarbrowser/status/2112214318611837243", "text": "In the past 90 days, Polar took 1 million actions on LinkedIn for its users.\n\nToday, we’re launching Polar for LinkedIn. Let Polar grow your business on autopilot.\n\nPolar is an AI browser that handles the repetitive work for you. Tell it what you need:\n\n→ Find prospects who match your ideal customer\n→ Research candidates and see why they fit\n→ Grow your network and draft hyper-personalized outreach\n\nPolar does the clicking for you. Take over anytime.\n\nCopy our best prompts and setup a recurring workflow in less than 5 minutes. Make LinkedIn work for you.\n\nDownload Polar for free → https://go.polarbrowser.com/linkedin-x", "name": "Polar Browser", "handle": "polarbrowser", "avatar": "https://pbs.twimg.com/profile_images/2082220044357152768/Ac6jRyfH_200x200.jpg", "likes": 190, "rts": 14, "replies": 50, "views": 122727, "ts": 1792426111, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112214181189726208/vid/avc1/1280x720/fzc0GU3jemaXAD5k.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112214181189726208/vid/avc1/3840x2160/u7vUKo30vM8f4bQh.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112214181189726208/img/KjFJE-z3bYDXn4NO.jpg", "dur": 61}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 4.44, "thread": [], "tier": "skim"}, {"id": "2110008207842422985", "url": "https://x.com/AiEvolutio58513/status/2110008207842422985", "text": "Reinforcement learning taught this robot to run in a way no human does, and there's a reason for it.\n\nPeople swing their arms mostly to cancel the twist that every stride sends through the torso. On a robot, the arm is motors, gears and wiring, and swinging it hard means high torque again and again for an entire lap.\n\nThe forward lean moves the center of mass out in front of the feet, where speed wants it. For a two-legged robot, that means less effort spent staying upright and more of every step turned into forward motion.\n\nInterested in AI?\n\nFollow @AiEvolutio58513 and never fall behind.\n\nI track ChatGPT, Claude, and every tool quietly changing how we work and create, then hand you the tested signals.", "name": "AI Evolution", "handle": "AiEvolutio58513", "avatar": "https://pbs.twimg.com/profile_images/2051404095026810880/ojNDixza_200x200.png", "likes": 78, "rts": 24, "replies": 7, "views": 14376, "ts": 1791900133, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2110008175542022144/vid/avc1/640x360/PnMOLZCc2G0CVwuh.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2110008175542022144/vid/avc1/1280x720/jLvI4O1vJP1Hezlv.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2110008175542022144/img/FrV2uWhVN03T__Id.jpg", "dur": 38}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 4.42, "thread": [], "tier": "skim"}, {"id": "2112394613847941139", "url": "https://x.com/ValsAI/status/2112394613847941139", "text": "Finance Agent v2.1 has a new panel of judge models and now fails answers that hedge between values. Excel Modeling is now graded by GPT-6 Luna. Code Migration runs every model on the Pi agent harness with revised hidden tests.\n\nHarvey's LAB judges can now see tracked changes in redlined documents. We also made Tax Agent Bench stricter: a question only counts if every rubric check passes.", "name": "Vals AI", "handle": "ValsAI", "avatar": "https://pbs.twimg.com/profile_images/2087888189185007616/r9Zu091v_200x200.png", "likes": 15, "rts": 0, "replies": 1, "views": 1164, "ts": 1792469096, "media": [], "quote": null, "reply_to": "2112394611515920459", "cat": "AI Models & Labs", "score": 4.42, "thread": [], "tier": "skim"}, {"id": "2112573266032578712", "url": "https://x.com/ArtificialAnlys/status/2112573266032578712", "text": "By use case on AA-Image-Editing v2.1, Fibo 2.0 ranks highest for everyday consumer edits and our hardest Frontier prompts, at #14 on both\n\nUse cases measure the real-world work the image is for, grounded in how consumers and enterprises use image editing.\n\nIts strongest use cases are everyday consumer edits and our most challenging prompts: it ranks #14 in both Consumer and Frontier. It sits furthest from the frontier in Retail & Ecommerce and Animation & Gaming. Against Fibo Edit, it scores higher on all 10 use cases, by the most in UIUX Design and Marketing & Advertising.\n\n➤ Consumer covers everyday personal use, like generating book covers, stock images and illustration.\n\n➤ Frontier is our set of especially challenging prompts, written to test capabilities at and beyond what today's best models can do.", "name": "Artificial Analysis", "handle": "ArtificialAnlys", "avatar": "https://pbs.twimg.com/profile_images/2042402069320290304/A8C1lP07_200x200.jpg", "likes": 7, "rts": 0, "replies": 1, "views": 572, "ts": 1792511690, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFYQyUb0AAOYOc.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVFYSTNa4AAW8CO.jpg?name=orig"}], "quote": null, "reply_to": "2112573262723191280", "cat": "AI Video, Art & Music", "score": 4.42, "thread": [], "tier": "skim"}, {"id": "2112612334111961134", "url": "https://x.com/ammaar/status/2112612334111961134", "text": "@dhaiwat Ok next agent prompt:\nresearch all current teams and playing rosters and update each countries playing XI", "name": "Ammaar Reshi", "handle": "ammaar", "avatar": "https://pbs.twimg.com/profile_images/1749207435255164928/A2xzzpnT_200x200.jpg", "likes": 6, "rts": 0, "replies": 1, "views": 3561, "ts": 1792521005, "media": [], "quote": null, "reply_to": "2112483997762863187", "cat": "AI Tools & Agents", "score": 4.42, "thread": [{"id": "2112483997762863187", "url": "https://x.com/dhaiwat/status/2112483997762863187", "text": "cricket 07 with an online multiplayer mode. play with your friends\n\nall you need is a web browser\n\nlink: https://cricket07.dhaiwat.com", "name": "Dhaiwat", "handle": "dhaiwat", "avatar": "https://pbs.twimg.com/profile_images/2110578752581419008/Si76IqY8_200x200.jpg", "likes": 9345, "rts": 913, "replies": 405, "views": 638306, "ts": 1792490407, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVEL_UxakAANyEt.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVEMQoIawAAjm1_.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVEMsEPboAA9lbe.jpg?name=orig"}], "quote": null, "reply_to": null}], "tier": "skim"}, {"id": "2112438948081635667", "url": "https://x.com/agentsky_dev/status/2112438948081635667", "text": "The cheap model wasn't cheaper this time.\n\n⚡ Codex (GPT-6.1 Sol) — 4 min 44 s · $0.24\n⏱ DeepSeek Harness (V4.1 Flash) — 39 min 31 s · $0.43\n\nSame island prompt, one run each. Which island would you ship?", "name": "AgentSky", "handle": "agentsky_dev", "avatar": "https://pbs.twimg.com/profile_images/2090338223772069888/s0t9QjoP_200x200.jpg", "likes": 5, "rts": 1, "replies": 3, "views": 654, "ts": 1792479667, "media": [{"type": "video", "url": "https://video.twimg.com/ext_tw_video/2112438733958172672/pu/vid/avc1/540x540/SvKMTFXgLXQNjbgl.mp4?tag=12", "hd": "https://video.twimg.com/ext_tw_video/2112438733958172672/pu/vid/avc1/720x720/TTb6KXZHxUswn5MJ.mp4?tag=12", "thumb": "https://pbs.twimg.com/ext_tw_video_thumb/2112438733958172672/pu/img/kGn8TDoMhZCkgC1J.jpg", "dur": 16}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 4.41, "thread": [], "tier": "skim"}, {"id": "2112151262984900639", "url": "https://x.com/agentsky_dev/status/2112151262984900639", "text": "Which AI agent is actually worth paying for?\n\nAgentSky Arena lets you give multiple agents the same task, compare their outputs blind, and choose a winner before revealing their identities and costs.\n\nIts reported cost-per-pick figures show a striking gap:\n• DeepSeek Harness: $0.81\n• Codex: $13.20\n• Claude Code: $170\n\nThese come from small samples, vary by agent and model configuration, and aren’t fixed prices per task.\n\nThe takeaway: compare quality and cost on your actual work. Use those results to decide which agent earns a place in your workflow.\n\nTry your own comparison: https://agentsky.dev/arena", "name": "AgentSky", "handle": "agentsky_dev", "avatar": "https://pbs.twimg.com/profile_images/2090338223772069888/s0t9QjoP_200x200.jpg", "likes": 14, "rts": 1, "replies": 10, "views": 5896, "ts": 1792411077, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112151114644918272/vid/avc1/720x1280/iNToq1qDMcU2Ytti.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112151114644918272/vid/avc1/1080x1920/uuWmmv_PP5LAvHMZ.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112151114644918272/img/eB0cUgjSxcSSPRjJ.jpg", "dur": 32}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 4.41, "thread": [], "tier": "skim"}, {"id": "2112509203550224583", "url": "https://x.com/alibaba_cloud/status/2112509203550224583", "text": "What will define the next generation of AI models?\nJoin Xudong Guo @_traceur__ , Research Scientist, Qwen, Token Foundry, Alibaba Token Hub, at #ApsaraConference2026 in Amsterdam to explore how AI models are evolving to reason, adapt, and take action in the real world.\n\nDate & Time: Oct 29, 2026 | 9:30 AM – 12:10 PM CET\nLocation: Beurs van Berlage, Amsterdam\nRegister: https://click.alibabacloud.com/m/20000003603/ \n\n#ApsaraAmsterdam #AgenticEra #AIAgents #AlibabaCloud", "name": "Alibaba Cloud", "handle": "alibaba_cloud", "avatar": "https://pbs.twimg.com/profile_images/2049406152564461568/0-ZrbCS9_200x200.jpg", "likes": 3, "rts": 2, "replies": 1, "views": 4910, "ts": 1792496417, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVEjxrfaAAAS2vZ.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 4.41, "thread": [], "tier": "skim"}, {"id": "2112287506301686114", "url": "https://x.com/Brammflakes/status/2112287506301686114", "text": "DICE and from what I’ve heard Respawn are working on Battlefront 3. Not sure what that means for Battlefield.", "name": "Joe Brammer", "handle": "Brammflakes", "avatar": "https://pbs.twimg.com/profile_images/2096002119660638208/M1Qak5WE_200x200.jpg", "likes": 3019, "rts": 143, "replies": 150, "views": 193880, "ts": 1792443560, "media": [], "quote": {"id": "2112222971142316531", "url": "https://x.com/Daily_SWGames/status/2112222971142316531", "text": "🚨 Lucasfilm are \"aggressively\" pushing for a Star Wars Battlefront 3 according to a new rumour!\n\nBoth DICE and Bungie are in talks over a new Battlefront game.", "name": "Daily Star Wars Games", "handle": "Daily_SWGames", "avatar": "https://pbs.twimg.com/profile_images/1350482390133649425/MY4Ri0v5_200x200.jpg", "likes": 30087, "rts": 2295, "replies": 638, "views": 1681401, "ts": 1792428174, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVAdORpXwAAk3kq.png?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVAdTALWsAANCgd.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVAdWT3XcAAGFjF.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "Sports", "score": 4.4, "thread": [], "tier": "skim"}, {"id": "2112266418494537806", "url": "https://x.com/ArtificialAnlys/status/2112266418494537806", "text": "Where FLUX 3 Max sits against the frontier on AA-Video-T2V v2.1: highest in Physics, closest behind in Audio Synchronization and Dialogue & Lip Sync\n\nAA-Video-T2V v2.1 measures 10 capabilities and 10 use cases, each with its own leaderboard. Capabilities are the model skills a prompt is written to test.\n\nFLUX 3 Max scores highest of any model in Physics, and sits closest behind the frontier in Audio Synchronization and Dialogue & Lip Sync. It sits furthest from it in Camera Control and Human Anatomy. Against its base model FLUX 3, it scores higher on seven of the ten capabilities, by the most in Lighting & Materials and Complex Composition.\n\n➤ Physics covers mechanics, thermal effects, material interactions, fracture and deformation, optics, cause and effect, and counterfactual physics.\n\n➤ Dialogue & Lip Sync covers single- and multi-speaker dialogue, and voiceover vs on-screen speech.\n\n➤ Audio Synchronization covers diegetic sound effects, background music and score, and on- and off-screen sound.", "name": "Artificial Analysis", "handle": "ArtificialAnlys", "avatar": "https://pbs.twimg.com/profile_images/2042402069320290304/A8C1lP07_200x200.jpg", "likes": 15, "rts": 1, "replies": 3, "views": 2526, "ts": 1792438532, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVBBfzAaIAAYkdd.jpg?name=orig"}], "quote": null, "reply_to": "2112266414593827110", "cat": "AI Models & Labs", "score": 4.39, "thread": [{"id": "2112266414593827110", "url": "https://x.com/ArtificialAnlys/status/2112266414593827110", "text": "FLUX 3 Max from @fal, a post-trained version of @bfl_ai's FLUX 3, ranks #2 on AA-Video-I2V v1.1 (statistically tied for #1) and #4 on AA-Video-T2V v2.1, ahead of the base FLUX 3 on both\n\nFLUX 3 Max generates 5 to 20 second, 720p videos with native audio from a text prompt or a starting image. fal reports that it generates a 10 second video in under 12 seconds. We benchmarked it at the high reasoning level.\n\nFLUX 3 Max ranks #2 on AA-Video-I2V v1.1 and #4 on AA-Video-T2V v2.1, statistically tied with Dreamina Seedance 2.5 and MiniMax H3 (768p) on both, and ahead of its base model FLUX 3. On AA-Video-T2V v2.1, it scores highest of any model in the Physics capability, and in the Marketing & Advertising and Live-Action Film use cases.\n\nfal prices FLUX 3 Max at $10.20/min for 720p video, compared to $17.40/min for FLUX 3, and $24.60/min for Dreamina Seedance 2.5 and $5.40/min for MiniMax H3 (768p) on Image to Video. For the first three weeks of launch, fal is offering 75% off, at $2.55/min.\n\nCongratulations to @fal on the release!\n\nSee below for our detailed analysis and comparisons between FLUX 3 Max and other leading models on AA-Video-T2V v2.1 and AA-Video-I2V v1.1 🧵", "name": "Artificial Analysis", "handle": "ArtificialAnlys", "avatar": "https://pbs.twimg.com/profile_images/2042402069320290304/A8C1lP07_200x200.jpg", "likes": 267, "rts": 25, "replies": 15, "views": 23737, "ts": 1792438531, "media": [{"type": "gif", "url": "https://video.twimg.com/tweet_video/HVBBWzWbUAAbltB.mp4", "hd": "https://video.twimg.com/tweet_video/HVBBWzWbUAAbltB.mp4", "thumb": "https://pbs.twimg.com/tweet_video_thumb/HVBBWzWbUAAbltB.jpg", "dur": 0}], "quote": null, "reply_to": null}], "tier": "skim"}, {"id": "2112621610003988613", "url": "https://x.com/TechMDAI/status/2112621610003988613", "text": "Spaces form your CUA Agents. Hermes agent", "name": "TechMD", "handle": "TechMDAI", "avatar": "https://pbs.twimg.com/profile_images/2078917263621500929/wEaqlEVO_200x200.jpg", "likes": 2, "rts": 1, "replies": 1, "views": 564, "ts": 1792523217, "media": [], "quote": {"id": "2112589741879328979", "url": "https://x.com/trycua/status/2112589741879328979", "text": "1/ Hermes can now launch Cua Spaces.\n\nWhen a task needs a computer, Hermes creates a Space on your Mac, Windows PC or Linux box, does the work there, and deletes it when it's done. You and your team can jump into the same Space while it works.", "name": "Cua", "handle": "trycua", "avatar": "https://pbs.twimg.com/profile_images/2106056584929361920/XJWz9bZS_200x200.jpg", "likes": 553, "rts": 38, "replies": 13, "views": 33642, "ts": 1792515619, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112587707998429184/vid/avc1/1280x720/soQNgl8D9wGe2hYg.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112587707998429184/vid/avc1/1920x1080/2gkvhjtbmSj1b8yT.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112587707998429184/img/Mw28zf6fWZHG5RTw.jpg", "dur": 19}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 4.39, "thread": [], "tier": "skim"}, {"id": "2112193361373536697", "url": "https://x.com/AndrewYang/status/2112193361373536697", "text": "Wow this would be phenomenal.", "name": "Andrew Yang🧢⬆️🇺🇸", "handle": "AndrewYang", "avatar": "https://pbs.twimg.com/profile_images/1974998523805421568/0K2jK_mC_200x200.jpg", "likes": 3811, "rts": 111, "replies": 300, "views": 129123, "ts": 1792421114, "media": [], "quote": {"id": "2112089556615123114", "url": "https://x.com/elonmusk/status/2112089556615123114", "text": "Next year, I will give one of my SpaceX shares to every kid in America.\n\nThis will be the first of many.", "name": "Elon Musk", "handle": "elonmusk", "avatar": "https://pbs.twimg.com/profile_images/2103567689515954176/aR-Kjpp4_200x200.jpg", "likes": 615882, "rts": 62862, "replies": 43246, "views": 34369112, "ts": 1792396365, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "Everything Else", "score": 4.37, "thread": [], "tier": "skim"}, {"id": "2112269858431733951", "url": "https://x.com/arcee_ai/status/2112269858431733951", "text": "Catch @allisonology on the first episode of the new High Taste Testers show from Latent Space!", "name": "Arcee.ai", "handle": "arcee_ai", "avatar": "https://pbs.twimg.com/profile_images/1976103399113490433/HkRDFgYC_200x200.jpg", "likes": 9, "rts": 3, "replies": 2, "views": 972, "ts": 1792439352, "media": [], "quote": {"id": "2111244257579409664", "url": "https://x.com/latentspacepod/status/2111244257579409664", "text": "🆕 show: HIGH TASTE TESTERS\n\nWe convene top Al power users to  compare what actually works-and what falls apart once you start using it.@davis7, @benhylak, @dexhorthy, @allisonology, @altryne and @swyx give you unfiltered takes on @OpenAl DevDay, Dots vs Muse vs GrokBot vs Instinct, who's winning coding, personal assistants, and the gap between impressive Al capabilities and useful products.\n\nFrom Pi-powered personal agents and decision models to subagents, context management, prompt injection, and assistants that can spend money: what should you actually use?\n\nCHAPTERS\n00:00 Introducing High Taste Testers\n01:26 OpenAl DevDay: Dots, Spaces, and product execution\n10:28 Great models versus great products\n14:39 Agents versus assistants\n18:08 Building a personal assistant with Pi\n21:07 Decision models, Jev, and predictive interfaces\n32:46 Model speed, writing quality, and subagents\n37:29 Agent loops, forks, and context management\n43:19 Haiku, Muse Spark, and Grok\n50:00 Local models and coding benchmarks\n54:09 Prompt injection and assistants taking action\n57:50 Tools, payments, and assistant overload\n1:02:16 Delegation, computer use, and everyday workflows\n1:10:48 Al hardware and closing thoughts\n\nTHANKS TO THE TESTERS\nBen Davis - @davis7\nBen Hylak - @benhylak\nDex Horthy - @dexhorthy\nAllison Durham - @allisonology \nAlex Volkov - @altryne", "name": "Latent.Space", "handle": "latentspacepod", "avatar": "https://pbs.twimg.com/profile_images/1888346877428641792/rMxtG84Z_200x200.jpg", "likes": 100, "rts": 14, "replies": 15, "views": 33139, "ts": 1792194830, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2111242884112695296/vid/avc1/1280x720/QFWHzXyTOHNZHPrt.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2111242884112695296/vid/avc1/1920x1080/APRCPknj3fOOPU5y.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2111242884112695296/img/CncGptGvOfVkkvgY.jpg", "dur": 4520}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 4.36, "thread": [], "tier": "skim"}, {"id": "2112602617125675432", "url": "https://x.com/omx0r/status/2112602617125675432", "text": "I GOT HERMES ON REASON NETWORK 🪽\n\nit's not on their list but it works. now my @bot in the cloud talks to hermes agent on my pc in one network\n\nfree p2p and open source. setup took one line\n\nwho else is running hermes on it?", "name": "Omar 🪽", "handle": "omx0r", "avatar": "https://pbs.twimg.com/profile_images/2108594027209576448/Pq0merQq_200x200.jpg", "likes": 5, "rts": 0, "replies": 1, "views": 233, "ts": 1792518688, "media": [], "quote": {"id": "2112539998352523575", "url": "https://x.com/reasonmachines/status/2112539998352523575", "text": "Let your Claude Code / Codex talk to your Grok Bot, Muse or any other agents online  \n\nFree, P2P Encrypted and Open Source\n\nIntroducing Reason Network OSS,  \n\nLoop in and talk to your teammates agents too!\n\nTell your agent \"Join the Reason Network\" https://reasonmachines.com/network", "name": "Reason", "handle": "reasonmachines", "avatar": "https://pbs.twimg.com/profile_images/2112534120907915264/4MgxEHTs_200x200.jpg", "likes": 1759, "rts": 109, "replies": 113, "views": 217748, "ts": 1792503759, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112539971378896897/vid/avc1/1280x720/0bjkStjjEYzRnx7_.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112539971378896897/vid/avc1/1920x1080/yI-1xclfzqMRrqfA.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112539971378896897/img/mdaYX9R6ijsiboOq.jpg", "dur": 24}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 4.36, "thread": [], "tier": "skim"}, {"id": "2112597162924351909", "url": "https://x.com/steipete/status/2112597162924351909", "text": "Two weeks ago I kicked off a loop to move OpenClaw's Lit-based Web frontend to Solid 2.0.\n\nTook ~6 days until we could remove Lit, and another week to move patterns to idiomatic Solid.\n\nI checked in with the session every other day, overall the process was mostly automatic. Took about ~600 PRs.\n\nResult: Smaller JS and CSS footprint and much more fine-grained update control. Everything feeling more snappy and responsive. https://team.openclaw.ai/chat/roboclaw/timeline-of-solid-js-to-lit-pr-refactors-5ba10f632c29434c9f79a92c3c16a7a3", "name": "Peter Steinberger 🦞", "handle": "steipete", "avatar": "https://pbs.twimg.com/profile_images/1131851609774985216/OcsssQ9J_200x200.png", "likes": 942, "rts": 40, "replies": 102, "views": 119154, "ts": 1792517388, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFxsUJbcAAlGap.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 4.35, "thread": [], "tier": "skim"}, {"id": "2112342538514530784", "url": "https://x.com/TimSweeneyEpic/status/2112342538514530784", "text": "Hello from Shanghai, where I’ll be presenting at UnrealFest later this week. And two weeks later, UnrealFest Tokyo.", "name": "Tim Sweeney", "handle": "TimSweeneyEpic", "avatar": "https://pbs.twimg.com/profile_images/795819168629198849/SBY3ARvZ_200x200.jpg", "likes": 2295, "rts": 53, "replies": 205, "views": 59370, "ts": 1792456681, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVCMVEaaoAA95nW.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 4.35, "thread": [], "tier": "skim"}, {"id": "2112689985111650784", "url": "https://x.com/ValsAI/status/2112689985111650784", "text": "Telling the chatbot it was talking to a teen cut failures from 43.3% to 24.9%. Emotional dependence failures fell from 53.6% to 14.9%. But no chatbot reached zero, and the prompt did nothing for indirect suicide risk: 51.7% of ratings failed without it, 52.3% with it.", "name": "Vals AI", "handle": "ValsAI", "avatar": "https://pbs.twimg.com/profile_images/2087888189185007616/r9Zu091v_200x200.png", "likes": 3, "rts": 0, "replies": 1, "views": 90, "ts": 1792539518, "media": [], "quote": null, "reply_to": "2112689983333306732", "cat": "Research & Safety", "score": 4.35, "thread": [{"id": "2112689980976050281", "url": "https://x.com/ValsAI/status/2112689980976050281", "text": "We tested 18 AI chatbots on teen safety with SAFE-Teen, the first teen safety benchmark built with clinicians that follows whole conversations instead of grading the first answer.\n\nEvery chatbot failed. 54.0% of conversations had at least one safety failure. The range was wide: 14.0% for GPT-6.1 Sol, 62.4% for Gemini 3.8 Flash.", "name": "Vals AI", "handle": "ValsAI", "avatar": "https://pbs.twimg.com/profile_images/2087888189185007616/r9Zu091v_200x200.png", "likes": 26, "rts": 2, "replies": 3, "views": 1995, "ts": 1792539518, "media": [{"type": "gif", "url": "https://video.twimg.com/tweet_video/HVHH08la4AA6enT.mp4", "hd": "https://video.twimg.com/tweet_video/HVHH08la4AA6enT.mp4", "thumb": "https://pbs.twimg.com/tweet_video_thumb/HVHH08la4AA6enT.jpg", "dur": 0}], "quote": null, "reply_to": null}, {"id": "2112689983333306732", "url": "https://x.com/ValsAI/status/2112689983333306732", "text": "The failures fall into three groups: they miss signs of danger, they step into a clinicians role, and they encourage emotional attachment.\n\nWe found that emotional attachment failed the most, about 51.8% of the time.", "name": "Vals AI", "handle": "ValsAI", "avatar": "https://pbs.twimg.com/profile_images/2087888189185007616/r9Zu091v_200x200.png", "likes": 5, "rts": 0, "replies": 1, "views": 235, "ts": 1792539518, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVHH69XbsAA20Oc.jpg?name=orig"}], "quote": null, "reply_to": "2112689980976050281"}], "tier": "skim"}, {"id": "2112485832678576173", "url": "https://x.com/nofil_ai/status/2112485832678576173", "text": "pi durable + cua spaces and you've basically got grok bot/dots alternative right?", "name": "Nofil", "handle": "nofil_ai", "avatar": "https://pbs.twimg.com/profile_images/1842074622273191936/8_OgHn-r_200x200.jpg", "likes": 3, "rts": 1, "replies": 2, "views": 418, "ts": 1792490845, "media": [], "quote": {"id": "2112228154651881479", "url": "https://x.com/trycua/status/2112228154651881479", "text": "1/ Introducing the Cua Spaces SDK.\n\nEvery big lab now ships a bot with its own computer: Grok Bot, Muse, dots. None let you bring your own. With Cua Spaces, now you can. \n\nPut Claude Code, Codex or any agent on compute you choose, and run jobs across all your computers at once.", "name": "Cua", "handle": "trycua", "avatar": "https://pbs.twimg.com/profile_images/2106056584929361920/XJWz9bZS_200x200.jpg", "likes": 3237, "rts": 222, "replies": 158, "views": 410187, "ts": 1792429410, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112223219252088832/vid/avc1/1280x720/I6_NaL1Cg-XWB-iq.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112223219252088832/vid/avc1/1920x1080/AHMslWsH_vMoQKku.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112223219252088832/img/EHvyGokJ8bsir4qa.jpg", "dur": 12}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 4.34, "thread": [], "tier": "skim"}, {"id": "2112160918440481203", "url": "https://x.com/TokenRouter_US/status/2112160918440481203", "text": "The 🐰 is out of the bag. It’s MiniMax M3.1 Flash from @MiniMax_AI, and it’s now on TokenRouter.\n\nM3.1 Flash scores 73.7% on DeepSWE v1.1, so it can burrow into a real codebase and come back with working fixes. On AutomationBench-AA it reaches 62.2, a test of business workflows that jump across several SaaS tools before the job is done. Output costs $0.60 per million tokens, which is not many carrots for a model this fast on its feet.\n\nLet it loose on TokenRouter: https://www.tokenrouter.com/models", "name": "TokenRouter", "handle": "TokenRouter_US", "avatar": "https://pbs.twimg.com/profile_images/2051766471081308160/GuxBHQaH_200x200.jpg", "likes": 23, "rts": 1, "replies": 2, "views": 2773, "ts": 1792413379, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HU_mag1aoAATnbq.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 4.34, "thread": [], "tier": "skim"}, {"id": "2112577565319917853", "url": "https://x.com/derek_price_/status/2112577565319917853", "text": "@stalman https://x.com/trycua/status/2112228154651881479?s=20 Maybe promising?", "name": "Derek Price", "handle": "derek_price_", "avatar": "https://pbs.twimg.com/profile_images/1432949176640417794/bnWv_Ne1_200x200.jpg", "likes": 4, "rts": 1, "replies": 0, "views": 389, "ts": 1792512716, "media": [], "quote": {"id": "2112228154651881479", "url": "https://x.com/trycua/status/2112228154651881479", "text": "1/ Introducing the Cua Spaces SDK.\n\nEvery big lab now ships a bot with its own computer: Grok Bot, Muse, dots. None let you bring your own. With Cua Spaces, now you can. \n\nPut Claude Code, Codex or any agent on compute you choose, and run jobs across all your computers at once.", "name": "Cua", "handle": "trycua", "avatar": "https://pbs.twimg.com/profile_images/2106056584929361920/XJWz9bZS_200x200.jpg", "likes": 3237, "rts": 222, "replies": 158, "views": 410141, "ts": 1792429410, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112223219252088832/vid/avc1/1280x720/I6_NaL1Cg-XWB-iq.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112223219252088832/vid/avc1/1920x1080/AHMslWsH_vMoQKku.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112223219252088832/img/EHvyGokJ8bsir4qa.jpg", "dur": 12}], "quote": null, "reply_to": null}, "reply_to": "2112568859266035779", "cat": "AI Models & Labs", "score": 4.32, "thread": [], "tier": "skim"}]);